#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Compare generic and model-derived default sampling on a frozen coding fixture","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd)
campaign="$root/benchmarks/intel-1340p/gemma-generation-parity-20260916"
out="$campaign/unspecified-sampling"
live="$root/build-gemma-zero-copy-vulkan";candidate="$root/build-gemma-generation-parity";runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime"
model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf";draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf";production=llama-gemma-zero-copy.service
mkdir -p "$out/runs";export XDG_RUNTIME_DIR=/run/user/$(id -u);export DBUS_SESSION_BUS_ADDRESS=unix:path=$XDG_RUNTIME_DIR/bus
restore() { local rc=$?;for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-parity-quality-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done;systemctl --user start "$production">/dev/null 2>&1||true;local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];systemctl --user stop "$production"
prompt=$(bun -e "import{normaliseTagsFixture as f}from'./benchmarks/intel-1340p/gemma-optimization-t02-20260911/fixtures';process.stdout.write(f.prompt)")
run_one() { local arm=$1 seed=$2;local port=$3;local unit="gemma-parity-quality-${arm}-${seed}.service";local dir="$out/runs/${arm}-${seed}";[[ ! -e $dir ]];mkdir -p "$dir";local build=$live;local extra=();if [[ $arm == candidate ]];then build=$candidate;extra=(--draft-min 1 --threadpools 0 --model-sampling 1);fi;systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 --setenv=LD_LIBRARY_PATH="$build/bin:$runtime" --setenv=GGML_VK_VISIBLE_DEVICES=0 --setenv=GGML_VK_EXPERIMENTAL_ATTN_MODE=f32 "$build/bin/llama-gemma-zero-copy-server" --model "$model" --draft "$draft" --alias "gemma-quality-$arm" --host 127.0.0.1 --port "$port" --ctx-size 32768 --batch-size 256 --ubatch-size 256 --threads 8 --threads-batch 16 --draft-max 3 "${extra[@]}" --max-output 2048 >"$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];jq -n --arg model gemma-4-e4b-qat-mtp-zero-copy --arg prompt "$prompt" --argjson seed "$seed" '{model:$model,messages:[{role:"user",content:$prompt}],seed:$seed,max_tokens:512,stream:false}' >"$dir/request.json";curl --max-time 180 -fsS "http://127.0.0.1:$port/v1/chat/completions" -H 'Content-Type: application/json' -H "X-Conversation-Id: quality-$arm-$seed" --data-binary @"$dir/request.json">"$dir/response.json";jq -e '.zero_copy.shared_bytes>0 and .zero_copy.copied_bytes==0' "$dir/response.json";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryPeak -p MemorySwapPeak>"$dir/service.txt";grep -Fx 'MemorySwapPeak=0' "$dir/service.txt";journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sha256sum "$dir"/* >"$dir/SHA256SUMS";}
run_one live 42 18842;run_one candidate 42 18942;run_one candidate 43 18943;run_one live 43 18843
# No model is resident while generated code is assessed/executed.
! systemctl --user list-units --state=active --plain --no-legend 'gemma-parity-quality-*.service'|grep -q .
bun "$campaign/evaluate-unspecified-sampling.ts"
sha256sum "$out/results.json">"$out/SHA256SUMS"
